    "content": "新华社里约热内卢11月6日电（记者赵焱）亚松森消息：巴拉圭前总统圣地亚哥·培尼亚当地时间6日晚在其位于首都亚松森的私人住所被警方逮捕，并暂时被软禁在家。 当天早些时候，巴拉圭国会通过对培尼亚的弹劾议案，认定其存在渎职等行为，解除其总统职务。 根据巴拉圭宪法，被弹劾后，培尼亚不再享有豁免权。巴拉圭总检察院随即发布命令，要求逮捕培尼亚，以调查直接导致他被弹劾的韦诺银行案，同时指控他任总统期间涉嫌背信、挪用公款和以权谋私等。 巴拉圭国家警察随即执行巴拉圭总检察院的命令，根据特别反腐败小组的相关规定，逮捕培尼亚并将其暂时软…"
