    "content": "谷歌发布Gemini Omni 1.2 Flash 单段视频时长增至15秒 谷歌宣布推出AI视频生成模型Gemini Omni 1.2 Flash，支持原生生成最长15秒的视频，并新增多轮对话式编辑能力。相比上一代模型，其视频时长上限从10秒提高至15秒，延长50%。 用户可按1秒为单位，将生成时长设定在3秒至15秒之间。谷歌称，新模型提升了对参考内容的遵循能力，可在多个镜头中更好地保持角色、物体、道具、场景和环境的一致性，减少运动及镜头切换过程中出现的视觉漂移或形态变化。该能力也适用于首尾关键帧之间的插值，以及在…"
