    "content": "近日，云南大理市洱管局在网络巡查中发现短视频平台出现“有人故意将宠物犬使劲扔进洱海水体”的相关内容后，该局迅速启动核查处置，一边前往现场走访摸排，确认事发地、事发时间，一边调取监控溯源，查找涉案当事人。经各方联动，市洱管局迅速锁定并联系上涉案当事人。 视频截图 经调查核实，11月1日中午，当事人一家沿洱海生态廊道游玩，行至下末村附近湖滨水域时，为给宠物犬洗澡，多次故意使劲将犬只扔进洱海水体。 大理市洱管局认定，该行为违反《云南省大理白族自治州洱海保护管理条例》第四十三条第（六）项规定，属于明令禁止的污染洱海水体违法…"
