    "author": "",
    "description": "当地时间11月6日晚间，一名中国公民在墨尔本市区不幸遇害身亡，目前犯罪嫌疑人已被当地警方缉拿归案。中国驻墨尔本总领馆对此高度重视，第一时间启动领事保护应急机制，要求警方全力彻查此案，依法、公正处理，严惩肇事凶手，切实维护中国公民合法权益。总领馆已及时与遇害者家属取得联系，通报情况，正在会同有关方面为家属善后提供便利。 中国驻墨尔本总领馆对同胞遇害深感悲痛，对其家属表示诚挚慰问，将继续同当地有关部门保持沟通，积极协助妥善处理有关善后事宜。",
    "content": "当地时间11月6日晚间，一名中国公民在墨尔本市区不幸遇害身亡，目前犯罪嫌疑人已被当地警方缉拿归案。中国驻墨尔本总领馆对此高度重视，第一时间启动领事保护应急机制，要求警方全力彻查此案，依法、公正处理，严惩肇事凶手，切实维护中国公民合法权益。总领馆已及时与遇害者家属取得联系，通报情况，正在会同有关方面为家属善后提供便利。 中国驻墨尔本总领馆对同胞遇害深感悲痛，对其家属表示诚挚慰问，将继续同当地有关部门保持沟通，积极协助妥善处理有关善后事宜。"
