    "content": "快科技11月7日消息， 谷歌在近日举行的2026年Android开发者大会上正式确认，Googlebook平台的硬件形态将从目前的翻盖式和可翻转式，进一步扩展至可拆卸屏幕形态。 这意味着该平台将正式引入类似微软Surface的二合一设计，填补便携平板领域的空白。 据了解，谷歌官方在主旨演讲中明确表示，Googlebook的硬件路线图将很快涵盖可拆卸类别。 简单来说，Googlebook并非简单的系统更名，它试图将安卓的应用生态与ChromeOS的办公属性深度融合，并原生集成了Gemini智能体AI工具。 相比于首批…"
