    "content": "2026年11月07日 前不久，与友人一道参访了全国重点文物保护单位河南巩义康百万庄园。在庄园主宅一院落过厅驻足，目光聚焦门楣上一方古匾。匾长一米有余，金底黑字，右侧两个篆体大字：留余。左侧密密麻麻十数行行楷小字，录有南宋廉吏王伯大《四留铭》：留有余，不尽之巧以还造化；留有余，不尽之禄以还朝廷；留有余，不尽之财以还百姓；留有余，不尽之福以还子孙。 来之前曾做功课，康百万庄园于明中叶始建，明末清初成规模；“河洛康家”十数代人居此，跨明、清和民国3个时期，凡400余年。心头曾升起疑云：俗话说“富不过三代”，康家何以数百…"
