    "description": "2026年11月07日 十几岁时，我作为越剧团学员到过浙江绍兴，绍兴有一座蕺山，蕺山长满水灵灵的蕺菜，蕺菜又叫鱼腥草。 相传，此地原名王驾山，勾践从吴国释放回越，带领百姓发愤图强，可天不遂人愿，第一年就遭遇灾荒，颗粒无收，越王便发动军民挖野菜。有一次，勾践在王驾山尝野菜中毒，连脸都肿起来了。左右劝道，国家的重担都压在大王肩上，大王一定要保重身体。越王摇头道，百姓受尽了苦头，度不过饥荒，复国何从谈起？要是没了百姓，哪还有什么国家？这一天夜…",
    "content": "2026年11月07日 十几岁时，我作为越剧团学员到过浙江绍兴，绍兴有一座蕺山，蕺山长满水灵灵的蕺菜，蕺菜又叫鱼腥草。 相传，此地原名王驾山，勾践从吴国释放回越，带领百姓发愤图强，可天不遂人愿，第一年就遭遇灾荒，颗粒无收，越王便发动军民挖野菜。有一次，勾践在王驾山尝野菜中毒，连脸都肿起来了。左右劝道，国家的重担都压在大王肩上，大王一定要保重身体。越王摇头道，百姓受尽了苦头，度不过饥荒，复国何从谈起？要是没了百姓，哪还有什么国家？这一天夜里，忽降一场透雨，次日拂晓，漫山遍野长出一种小草，沾着露水迎着朝霞闪光。勾践拔起…"
