    "description": "2026年11月07日 北方工业重镇、港口城市、万国建筑博览会……这些词，随时都能标注在“天津”前面。但我始终觉得，任何一个词都不能完全概括天津的城市属性。天津是很难打上某个具体标签的城市，而每个人也能在非常熟悉的地方找到新的感悟。 比如天津古文化街，对于天津本地人来讲再熟悉不过，于初来乍到的外地人也是不容犹疑的打卡地。上世纪70年代初我上小学时，就和同学们来这一带买过空竹和鞭炮。那时这里叫宫南、宫北大街。 1985年天津市政府决定复建…",
    "content": "2026年11月07日 北方工业重镇、港口城市、万国建筑博览会……这些词，随时都能标注在“天津”前面。但我始终觉得，任何一个词都不能完全概括天津的城市属性。天津是很难打上某个具体标签的城市，而每个人也能在非常熟悉的地方找到新的感悟。 比如天津古文化街，对于天津本地人来讲再熟悉不过，于初来乍到的外地人也是不容犹疑的打卡地。上世纪70年代初我上小学时，就和同学们来这一带买过空竹和鞭炮。那时这里叫宫南、宫北大街。 1985年天津市政府决定复建宫南、宫北大街，并于1986年元旦重新开街，有着700年历史的古街又有了新名——…"
