    "description": "新华社里约热内卢11月6日电（记者赵焱）亚松森消息：巴拉圭国会6日弹劾总统圣地亚哥·培尼亚后，副总统佩德罗·阿利亚纳在国会宣誓就任总统，接替培尼亚完成剩余一年零9个月的任期。 阿利亚纳在就职演说中承诺，所有在韦诺银行案中资金被冻结的客户都将取回他们的财产。 培尼亚被指控介入该私有银行业务，存在利益冲突、操纵金融、违规使用养老基金等问题。 当天早些时候，巴拉圭国会通过对培尼亚的弹劾议案，解除其总统职务。会议期间，巴拉圭参议院特别会议认定培…",
    "content": "新华社里约热内卢11月6日电（记者赵焱）亚松森消息：巴拉圭国会6日弹劾总统圣地亚哥·培尼亚后，副总统佩德罗·阿利亚纳在国会宣誓就任总统，接替培尼亚完成剩余一年零9个月的任期。 阿利亚纳在就职演说中承诺，所有在韦诺银行案中资金被冻结的客户都将取回他们的财产。 培尼亚被指控介入该私有银行业务，存在利益冲突、操纵金融、违规使用养老基金等问题。 当天早些时候，巴拉圭国会通过对培尼亚的弹劾议案，解除其总统职务。会议期间，巴拉圭参议院特别会议认定培尼亚被指控的多项罪名成立。 按照巴拉圭宪法，阿利亚纳在培尼亚被弹劾后接任总统职位…"
