    "description": "中菲两国执法部门星期五（11月6日）合作遣返100余名涉赌诈犯罪嫌疑人。 “中国驻菲律宾大使馆”微信公众号星期五发布上述消息，并称这是中菲执法部门合作打击跨国犯罪的又一重要成果。 中国驻菲使馆称，中方打击赌诈等跨国犯罪活动的立场坚定不移。2023年以来，中菲执法部门合作累计遣返犯罪嫌疑人2600余名。 使馆强调，中方愿同菲律宾执法部门密切合作，采取一切必要措施，维护两国正常人员和经贸往来秩序。 中国和菲律宾执法部门此前已有多次类似行动。…",
