    "content": "【编者按】 到一地，最多人愿与其合照者，是为“地标”。人们常常和地标合影，但较少知道该地标是如何形成的，和这座城市精神、市民性格又有怎样的互动。而这正是我们思考的起点，这些思考辑成《地标是如何炼成的》专题。 今天我们关注陕西西安的地标大雁塔。 海报设计：王璐瑶 站在西安大雁塔上，向北望去，亚洲规模最大的矩阵式音乐喷泉可尽收眼底；向南望去，是仿若梦回唐朝的大唐不夜城。 一千多年前，二十七岁的白居易中进士后，在大雁塔题名，留下了一句“慈恩塔下题名处，十七人中最少年”。 经过历史沧桑巨变后，新科进士“雁塔题名”的风俗早已…"
