    "description": "新华社惠灵顿11月7日电（记者易爱军）新西兰议会选举7日开始正式投票。民调显示，国家党领导的执政联盟与工党主导的反对阵营选情胶着。 新西兰全国设有2300多个投票站，于当地时间9时至19时开放。目前已初步登记近380万名选民，占预估合格选民总数的93.6%。7日为选举日，是选民最后的投票机会。 提前投票已于10月26日开启。据新西兰选举委员会统计，截至11月5日，已有超过166万张选票提前发出，多于2023年选举同一阶段的137万多张。…",
    "content": "新华社惠灵顿11月7日电（记者易爱军）新西兰议会选举7日开始正式投票。民调显示，国家党领导的执政联盟与工党主导的反对阵营选情胶着。 新西兰全国设有2300多个投票站，于当地时间9时至19时开放。目前已初步登记近380万名选民，占预估合格选民总数的93.6%。7日为选举日，是选民最后的投票机会。 提前投票已于10月26日开启。据新西兰选举委员会统计，截至11月5日，已有超过166万张选票提前发出，多于2023年选举同一阶段的137万多张。 新西兰总理克里斯托弗·拉克森领导的国家党在2023年大选中上台，寻求赢得第二个…"
