    "content": "11月6日，在法国巴黎，香港科技大学校长、中国科学院院士叶玉如教授（左）获颁“联合国教科文组织-赤道几内亚国际生命科学研究奖”（手机照片）。新华社记者 罗毓 摄 新华社巴黎11月6日电（记者罗毓）当地时间6日下午，第10届“联合国教科文组织-赤道几内亚国际生命科学研究奖”颁奖仪式在联合国教科文组织巴黎总部举行。香港科技大学校长、中国科学院院士叶玉如教授获奖，系第6位获得该奖项的中国科学家。 根据教科文组织介绍，叶玉如因在神经科学领域的杰出贡献获奖。她在大脑功能及阿尔茨海默病研究方面取得重要成果，发现新的生物标志物和…"
