    "content": "新华社纽约11月6日电 纽约股市三大股指6日涨跌不一。 截至当天收盘，道琼斯工业平均指数比前一交易日下跌237.33点，收于51285.73点，跌幅为0.46%；标准普尔500种股票指数上涨23.13点，收于7376.86点，涨幅为0.31%；纳斯达克综合指数上涨264.43点，收于24579.42点，涨幅为1.09%。 板块方面，标普500指数十一大板块七跌四涨。必需消费品板块和金融板块分别以1.21%和0.68%的跌幅领跌，科技板块和通信服务板块分别以1.26%和0.51%的涨幅领涨。"
