    "content": "新华社莫斯科11月6日电（记者栾海）俄罗斯总统新闻秘书佩斯科夫6日评价不久前结束的奥列什基人道主义援助行动时表示，俄美双方保持积极心态，愿继续开展人道主义工作。 佩斯科夫在当天举行的例行新闻发布会上说，俄总统特别代表德米特里耶夫和俄人权事务专员兰特拉托娃5日在华盛顿与美国总统特朗普的夫人梅拉尼娅的会面“非常积极”，“梅拉尼娅及其团队为在奥列什基市开展人道主义援助付出不少努力，他们与俄乌人权事务专员共同开展工作”。 佩斯科夫表示，俄美开展人道主义工作与双方政治接触“互为补充”，“是很好的实践”。 谈及与欧洲国家关系，…"
