    "content": "新华社华盛顿11月6日电（记者杨伶 熊茂伶）美国总统特朗普6日宣布，白宫办公厅副主任斯蒂芬·米勒将从9日起接替苏茜·怀尔斯，出任白宫办公厅主任。怀尔斯“将调至特朗普政治运营团队”。 特朗普在社交媒体发文宣布这一任命，称米勒是其“最信任的顾问之一”，而怀尔斯在担任白宫办公厅主任期间“做得非常棒”。 怀尔斯随后在社交媒体发文说，6日是她任职白宫办公厅主任的最后一天，虽然职责可能有变，但对总统的承诺不变。 据美媒报道，米勒一直是特朗普核心圈的重要成员，也是本届政府强硬移民政策的主要制定者之一，而怀尔斯长期担任特朗普的助手…"
