    "content": "香港民主派人士黄之锋原定明年1月出狱，却在距离重获自由只剩两个多月时，再迎来一纸判书：香港高等法院星期四（11月5日）就他的第二起国安案判监10年。这意味着，上月刚在狱中度过30岁生日的他，预计要到2036年11月才能获释，届时他将年满40岁。 黄之锋今年9月承认“串谋勾结外国或者境外势力危害国家安全”罪。法庭指控他在2020年7月至11月间，与前香港众志主席罗冠聪等人串谋，请求外国对中国大陆及香港实施制裁等行动。法官谭耀豪认定罪行重大，以13年为量刑起点，考虑认罪及求情后减至10年，其中两个月零两天与现有刑期同期…"
